// Mesma conferencia do fluxo ficticio: segredo A sobre horario + corpo bruto,
// janela de 5 minutos, tarefa dentro da validade.
const { createHmac, timingSafeEqual } = require('crypto');

const item = $input.first();
const headers = item.json.headers ?? {};
const timestamp = headers['x-atendara-timestamp'] ?? '';
const signature = headers['x-atendara-signature'] ?? '';
const raw = item.binary?.data?.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body ?? {});

const expected = createHmac('sha256', $env.ATENDARA_TASK_SECRET).update(`${timestamp}.${raw}`).digest('hex');
const assinaturaValida =
  expected.length === String(signature).length &&
  timingSafeEqual(Buffer.from(expected), Buffer.from(String(signature)));
const dentroDaJanela = Math.abs(Date.now() - Date.parse(timestamp)) <= 300000;

const tarefa = JSON.parse(raw);
const vencida = Date.parse(tarefa.expiresAt) <= Date.now();
// Contrato 2: a tarefa diz o que montar. Sem o campo e a versao 1, que so
// conhecia modelo. Aviso sai por modelo aprovado — fora da janela de 24 h a
// Meta so entrega modelo, e lembrete nunca acontece dentro dela. Resposta na
// conversa sai como texto; quem confere a janela e o Atendara, antes de mandar.
const tipo = tarefa.messageType ?? 'TEMPLATE';
const tipoDesconhecido = tipo !== 'TEMPLATE' && tipo !== 'TEXT';
const semModelo = tipo === 'TEMPLATE' && !tarefa.template?.name;
const semTexto =
  tipo === 'TEXT' &&
  (typeof tarefa.body !== 'string' || !tarefa.body.trim() || tarefa.body.length > 4096 || Boolean(tarefa.template));
const semRemetente = !/^\d{5,30}$/.test(String(tarefa.providerSenderId ?? ""));

return [
  {
    json: {
      aceita:
        assinaturaValida && dentroDaJanela && !vencida && !tipoDesconhecido && !semModelo && !semTexto && !semRemetente,
      motivo: !assinaturaValida
        ? 'BAD_SIGNATURE'
        : !dentroDaJanela
          ? 'STALE_TIMESTAMP'
          : vencida
            ? 'TASK_EXPIRED'
            : tipoDesconhecido
              ? 'UNKNOWN_MESSAGE_TYPE'
              : semModelo
                ? 'NO_TEMPLATE'
                : semTexto
                  ? 'NO_TEXT'
                  : semRemetente
                    ? 'NO_SENDER'
                    : 'OK',
      tarefa
    }
  }
];

// Monta a chamada da Cloud API a partir do que o Atendara decidiu: modelo
// aprovado (aviso) ou texto pronto (resposta na conversa). O n8n nao decide
// texto, nao decide destinatario e nao consulta banco nenhum: o que ele faz e
// traduzir o contrato para o formato da Meta.
const tarefa = $json.tarefa;
if (!/^\d{5,30}$/.test(String(tarefa.providerSenderId ?? ""))) throw new Error("MISSING_PHONE_NUMBER_ID");

const base = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: tarefa.destination.replace(/^\+/, '')
};

let corpo;
if ((tarefa.messageType ?? 'TEMPLATE') === 'TEXT') {
  // Sem pre-visualizacao de link: o texto e do Atendara, mas um link nele
  // faria o WhatsApp buscar a pagina em nome da pessoa.
  corpo = { ...base, type: 'text', text: { preview_url: false, body: tarefa.body } };
} else {
  const modelo = tarefa.template;
  corpo = {
    ...base,
    type: 'template',
    template: {
      name: modelo.name,
      language: { code: modelo.language },
      components: [
        {
          type: 'body',
          parameters: modelo.parameters.map((valor) => ({ type: 'text', text: valor }))
        }
      ]
    }
  };
}

return [
  {
    json: {
      corpo,
      url: `https://graph.facebook.com/v25.0/${tarefa.providerSenderId}/messages`
    }
  }
];

// A resposta da Meta vira o resultado do contrato. Codigo de erro da Meta ->
// codigo NOSSO: a mensagem dela costuma repetir o numero, que e contato de
// paciente, e por isso nunca e copiada.
const { createHmac } = require('crypto');

const resposta = $json;
const tarefa = $('Conferir assinatura').first().json.tarefa;
const status = resposta.statusCode ?? 0;
const erro = resposta.body?.error ?? null;

const PERMANENTES = new Set([131026, 131051, 131052]);
// 131047: passaram as 24 horas desde a ultima mensagem da pessoa. So acontece
// com texto — modelo aprovado entra fora da janela — e nao e destino invalido:
// o numero volta a receber quando ela escrever de novo.
const JANELA_FECHADA = 131047;
// 130497 não descreve o telefone do destinatário: a conta remetente não pode
// enviar para aquele país. Tratá-lo como destino inválido esconderia que o
// número de teste americano não serve para validar um destinatário brasileiro.
const REMETENTE_NAO_AUTORIZADO = new Set([130497]);
const LIMITE = new Set([130429, 131048, 80007]);

let resultado;
if (status >= 200 && status < 300 && !erro) {
  resultado = {
    outcome: 'ACCEPTED',
    providerMessageId: resposta.body?.messages?.[0]?.id ?? null,
    failureCode: null
  };
} else if (erro && erro.code === JANELA_FECHADA) {
  resultado = { outcome: 'REJECTED', providerMessageId: null, failureCode: 'OUTSIDE_REPLY_WINDOW' };
} else if (erro && REMETENTE_NAO_AUTORIZADO.has(erro.code)) {
  resultado = { outcome: 'REJECTED', providerMessageId: null, failureCode: 'SENDER_NOT_ALLOWED' };
} else if (erro && PERMANENTES.has(erro.code)) {
  resultado = { outcome: 'REJECTED', providerMessageId: null, failureCode: 'INVALID_DESTINATION' };
} else if (erro && LIMITE.has(erro.code)) {
  resultado = { outcome: 'TEMPORARY_FAILURE', providerMessageId: null, failureCode: 'RATE_LIMITED' };
} else {
  resultado = { outcome: 'TEMPORARY_FAILURE', providerMessageId: null, failureCode: 'PROVIDER_UNAVAILABLE' };
}

const corpo = JSON.stringify({
  version: tarefa.version,
  taskId: tarefa.taskId,
  organizationId: tarefa.organizationId,
  attempt: tarefa.attempt,
  ...resultado
});

const timestamp = new Date().toISOString();
const assinatura = createHmac('sha256', $env.ATENDARA_CALLBACK_SECRET).update(`${timestamp}.${corpo}`).digest('hex');

return [{ json: { corpo, timestamp, assinatura, url: $env.ATENDARA_CALLBACK_URL } }];
